      group_company: 'Банк ВТБ(ПАО)',
      model_name: 'CRM. Модель прогнозирования амортизации ипотеки',
      model_desc:
        'Модель необходима для прогнозирования амортизации ипотеки. Под амортизацией понимается отношение фактического основного долга с учетом просрочки и без учета процентов к плановому значению на горизонте 12 месяцев. В первую очередь от модели требуется не точный прогноз амортизации, а высокая ранжирующая способность (высокая корреляция прогноза и факта), поскольку в дальнейшем на основании модельного прогноза клиенты будут разделены на группы с разной скоростью выгашивания кредитов. Финальный прогноз амортизации будет осуществляться в результате «калибровки» каждой группы на наиболее актуальных доступных данных. ',
