      model_desc:
        'Разработка отдельного модуля, который бы при расчете вероятности дефолта кроме финансовой отчетности на соло уровне также учитывал бы консолидированную финансовую отчетность группы связанных компаний, к которой относится рассматриваемый заемщик. И включение в базовую модель  – итоговый скоринговый балл на основе количественной и качественной информации о контрагенте. Включает в себя агрегированную информацию по следующим блокам (модулям) данных о клиенте – «Финансовая отчетность», «Кредитная история», «Судебные и исполнительные производства».',
